<?php
header('Content-Type: text/html; charset=UTF-8');
$ROOT=realpath(__DIR__);
$SKIP=['.git','node_modules','vendor','cache','tmp','logs'];
$TEXT='/\.(php|inc|phtml|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|xml|svg|yml|yaml)$/i';
function blocked($p){global $SKIP;foreach($SKIP as $s)if(preg_match('#(^|/)'.preg_quote($s,'#').'(/|$)#',$p))return true;return false;}
function rel($p,$r){$x=realpath($p);return $x?ltrim(str_replace('\\','/',substr($x,strlen($r))),'/'):'';}
function scan($root){global $TEXT;$files=[];$dirs=[];$n=0;
 $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);
 foreach($it as $f){$p=rel($f->getPathname(),$root);if(!$p||blocked($p)||$p==='site-wire-live.php'||$p==='site-wire-jarvis.php')continue;if($f->isDir()){$dirs[]=$p;continue;}if($f->isFile()){ $files[$p]=['size'=>$f->getSize(),'text'=>(bool)preg_match($TEXT,$p)];if(++$n>12000)break;}}
 sort($dirs);ksort($files);$refs=[];$rx=[
 '/\b(?:require|require_once|include|include_once)\s*\(?\s*[\'\"]([^\'\"]+)[\'\"]/i',
 '/\b(?:import|export)\s+(?:[^\'\";]+?\s+from\s+)?[\'\"]([^\'\"]+)[\'\"]/i',
 '/\b(?:src|href)\s*=\s*[\'\"]([^\'\"]+)[\'\"]/i',
 '/url\(\s*[\'\"]?([^\'\"\)]+)[\'\"]?\s*\)/i'];
 foreach($files as $p=>$m){if(!$m['text']||$m['size']>350000)continue;$s=@file_get_contents($root.'/'.$p);if($s===false)continue;$vals=[];foreach($rx as $re){preg_match_all($re,$s,$mm);foreach($mm[1]??[] as $v){$v=trim(preg_replace('/[#?].*$/','',$v));if($v&&!preg_match('/^(https?:|data:|mailto:|javascript:|#|\/\/)/i',$v))$vals[]=$v;}}foreach(array_unique($vals) as $v){$base=dirname($p);$c=ltrim(str_replace('\\','/',($v[0]==='/'?$v:$base.'/'.$v)),'/');foreach([$c,$c.'.php',$c.'.js',$c.'.css',$c.'.json',$c.'.html',$c.'/index.php',$c.'/index.html'] as $z)if(isset($files[$z])){$refs[]=['from'=>$p,'to'=>$z];break;}}}
 return ['root'=>basename($root),'files'=>array_keys($files),'dirs'=>$dirs,'refs'=>$refs,'time'=>date('H:i:s')];}
if(isset($_GET['scan'])){set_time_limit(20);$d=scan($ROOT);header('Cache-Control:no-store');header('Content-Type:application/json');echo json_encode($d,JSON_UNESCAPED_SLASHES);exit;}
if(isset($_GET['pulse'])){header('Cache-Control:no-store');header('Content-Type:application/json');echo json_encode(['ok'=>1,'time'=>date('H:i:s'),'ts'=>microtime(true)]);exit;}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz — JARVIS Core</title><style>
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#03070d;color:#dff8ff;font-family:Inter,system-ui,Segoe UI,sans-serif}body:after{content:"";position:fixed;inset:0;pointer-events:none;background:radial-gradient(circle at 50% 50%,#06324822,transparent 55%)}#cv{position:fixed;inset:0;width:100%;height:100%;cursor:grab}.drag{cursor:grabbing!important}.top{position:fixed;z-index:5;top:20px;left:24px;right:24px;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}.title{pointer-events:auto}.micro{font:700 8px ui-monospace;color:#52677d;letter-spacing:2px}.micro b{color:#48efae}.title h1{margin:6px 0 3px;font-size:28px;letter-spacing:-1.5px}.title h1 span{color:#27dfff}.sub{font:8px ui-monospace;color:#50647c}.right{display:flex;gap:7px}.chip{padding:8px 11px;border:1px solid #ffffff12;background:#07121ddd;border-radius:10px;min-width:65px}.chip small{display:block;font:700 7px ui-monospace;color:#52677d}.chip strong{font:800 12px ui-monospace}.live{color:#48efae}.search{position:fixed;z-index:6;top:108px;left:24px;width:230px;padding:10px 12px;border:1px solid #ffffff12;background:#07121ddd;border-radius:10px;color:#dff8ff;outline:0;font:700 9px ui-monospace}.side{position:fixed;z-index:7;right:24px;top:108px;width:300px;padding:15px;border:1px solid #ffffff12;background:#07121ded;border-radius:14px;display:none}.side.on{display:block}.side button{float:right;border:0;background:none;color:#6e8297;font-size:20px}.side .label{font:700 7px ui-monospace;color:#536a82;letter-spacing:1.5px}.side h2{font-size:15px;margin:7px 0}.side .path{font:8px ui-monospace;color:#73eaff;word-break:break-all}.side .info{font:8px ui-monospace;color:#71859b;line-height:1.8;margin-top:8px}.bottom{position:fixed;z-index:6;left:24px;bottom:20px;display:flex;gap:6px}.btn{border:1px solid #ffffff12;background:#07121ddd;color:#9db3c9;border-radius:9px;padding:8px 11px;font:800 8px ui-monospace;cursor:pointer}.btn:hover{border-color:#27dfff66;color:#fff}.status{position:fixed;z-index:6;left:24px;bottom:57px;font:700 8px ui-monospace;color:#50647c}.dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#48efae;box-shadow:0 0 12px #48efae;margin-right:6px}.loading{position:fixed;z-index:20;inset:0;display:grid;place-items:center;background:#03070df5}.loader{text-align:center}.core{width:58px;height:58px;margin:auto;border-radius:50%;border:1px solid #27dfff66;box-shadow:0 0 35px #27dfff22,inset 0 0 22px #27dfff18;position:relative;animation:breathe 1.7s ease-in-out infinite}.core:before,.core:after{content:"";position:absolute;inset:9px;border-radius:50%;border:1px solid #48efae44}.core:after{inset:18px;border-color:#27dfff88}.loader b{display:block;margin-top:14px;font:900 11px ui-monospace;letter-spacing:1.5px}.loader small{display:block;margin-top:5px;color:#62758c;font:8px ui-monospace}.err{color:#ff7580!important}@keyframes breathe{50%{transform:scale(1.12);box-shadow:0 0 55px #27dfff33,inset 0 0 28px #27dfff22}}@media(max-width:700px){.top{left:12px;right:12px;top:12px}.title h1{font-size:21px}.sub{display:none}.chip{min-width:48px;padding:6px}.chip small{font-size:6px}.chip strong{font-size:9px}.search{left:12px;top:82px;width:190px}.side{left:12px;right:12px;top:82px;width:auto}.bottom{left:12px;bottom:12px}.status{left:12px;bottom:48px}}
</style></head><body><canvas id="cv"></canvas><div class="loading" id="loading"><div class="loader"><div class="core"></div><b>JARVIS NEURAL CORE</b><small id="msg">Initializing live site map…</small></div></div><div class="top"><div class="title"><div class="micro"><b>●</b> SMARTTOOLZ / LIVE SYSTEM</div><h1>Repository <span>Mind</span></h1><div class="sub">SERVER FILESYSTEM • REAL DEPENDENCIES • LIVE SIGNALS</div></div><div class="right"><div class="chip"><small>FILES</small><strong id="files">—</strong></div><div class="chip"><small>LINKS</small><strong id="links">—</strong></div><div class="chip"><small>STATE</small><strong id="state" class="live">BOOT</strong></div></div></div><input class="search" id="search" placeholder="find file or folder…"><div class="side" id="side"><button id="close">×</button><div class="label">ACTIVE NODE</div><h2 id="name"></h2><div class="path" id="path"></div><div class="info" id="info"></div></div><div class="status"><span class="dot"></span>SERVER <b id="heartbeat">CONNECTING</b></div><div class="bottom"><button class="btn" id="fit">FIT</button><button class="btn" id="pause">PAUSE</button><button class="btn" id="scan">RESCAN</button></div>
<script>
const cv=document.getElementById('cv'),ctx=cv.getContext('2d');let W=0,H=0,dpr=1,N=[],E=[],selected=null,hover=null,zoom=.82,panX=0,panY=0,down=false,lastX=0,lastY=0,paused=false,signal=0;
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return(h>>>0)/4294967296}
function build(D){N=[];E=[];const map=new Map;for(const p of D.dirs){const n={id:'d:'+p,path:p,name:p.split('/').pop()+'/',folder:1,x:0,y:0,r:7};N.push(n);map.set(n.id,n)}for(const p of D.files){const n={id:'f:'+p,path:p,name:p.split('/').pop(),folder:0,x:0,y:0,r:2.8};N.push(n);map.set(n.id,n)}const seen=new Set;for(const n of N){const parts=n.path.split('/');if(parts.length>1){const parent=map.get('d:'+parts.slice(0,-1).join('/'));if(parent){const k=parent.id+'>'+n.id;E.push({a:parent,b:n,type:'tree',phase:hash(k)});seen.add(k)}}}for(const r of D.refs){const a=map.get('f:'+r.from),b=map.get('f:'+r.to);if(a&&b){const k=a.id+'>'+b.id;if(!seen.has(k)){E.push({a,b,type:'dep',phase:hash(k)});seen.add(k)}}}layout();document.getElementById('files').textContent=D.files.length;document.getElementById('links').textContent=D.refs.length;document.getElementById('state').textContent='LIVE';document.getElementById('loading').style.display='none'}
function layout(){const cx=W/2,cy=H/2,folders=N.filter(n=>n.folder&&!n.path.includes('/'));const radius=Math.min(W,H)*.24;folders.forEach((f,i)=>{const a=-Math.PI/2+i*Math.PI*2/Math.max(1,folders.length);f.x=cx+Math.cos(a)*radius;f.y=cy+Math.sin(a)*radius;const kids=N.filter(n=>!n.folder&&n.path.split('/')[0]===f.path);const rr=Math.min(W,H)*Math.min(.18,.08+kids.length*.0008);kids.forEach((n,j)=>{const aa=a-.85+(j/Math.max(1,kids.length-1))*1.7;n.x=f.x+Math.cos(aa)*rr;n.y=f.y+Math.sin(aa)*rr})});const loose=N.filter(n=>!n.folder&&!folders.some(f=>n.path.split('/')[0]===f.path));loose.forEach((n,i)=>{const a=i*Math.PI*2/Math.max(1,loose.length);n.x=cx+Math.cos(a)*Math.min(W,H)*.39;n.y=cy+Math.sin(a)*Math.min(W,H)*.39})}
function P(n){return{x:n.x*zoom+panX,y:n.y*zoom+panY}}function hit(x,y){let best=null,bd=15;for(const n of N){const p=P(n),d=Math.hypot(x-p.x,y-p.y);if(d<bd){bd=d;best=n}}return best}
function draw(t){ctx.clearRect(0,0,W,H);const active=selected||hover;for(const e of E){const a=P(e.a),b=P(e.b),hot=active&&(e.a===active||e.b===active);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=hot?'rgba(39,223,255,.82)':e.type==='dep'?'rgba(39,223,255,.16)':'rgba(143,112,255,.07)';ctx.lineWidth=hot?1.8:e.type==='dep'?1:.45;ctx.stroke();if(e.type==='dep'&&!paused){const q=(t/1900+e.phase)%1,x=a.x+(b.x-a.x)*q,y=a.y+(b.y-a.y)*q;ctx.beginPath();ctx.arc(x,y,2.1,0,Math.PI*2);ctx.fillStyle='#48efae';ctx.shadowBlur=13;ctx.shadowColor='#48efae';ctx.fill();ctx.shadowBlur=0;signal++}}for(const n of N){const p=P(n),hot=n===active,r=n.folder?6.5:hot?5:2.5;ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fillStyle=n.folder?'#8f70ff':hot?'#68edff':'#153047';ctx.shadowBlur=hot?18:6;ctx.shadowColor=n.folder?'#8f70ff':'#27dfff';ctx.fill();ctx.shadowBlur=0;if(hot||zoom>.95){ctx.fillStyle=hot?'#effcff':'#6b7e95';ctx.font=(hot?'9':'7')+'px ui-monospace';ctx.fillText(n.name,p.x+r+4,p.y+3)}}requestAnimationFrame(draw)}
cv.onpointerdown=e=>{down=true;lastX=e.clientX;lastY=e.clientY;cv.classList.add('drag')};addEventListener('pointermove',e=>{if(down){panX+=e.clientX-lastX;panY+=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY}hover=hit(e.clientX,e.clientY)});addEventListener('pointerup',e=>{down=false;cv.classList.remove('drag');const n=hit(e.clientX,e.clientY);if(n){selected=n;document.getElementById('side').classList.add('on');document.getElementById('name').textContent=n.name;document.getElementById('path').textContent=n.path;document.getElementById('info').textContent=(n.folder?'FOLDER':'FILE')+'  •  '+E.filter(x=>x.a===n||x.b===n).length+' connections'}});cv.onwheel=e=>{e.preventDefault();zoom=Math.max(.25,Math.min(4,zoom*Math.exp(-e.deltaY*.001)))};
document.getElementById('close').onclick=()=>document.getElementById('side').classList.remove('on');document.getElementById('pause').onclick=e=>{paused=!paused;e.target.textContent=paused?'PLAY':'PAUSE';document.getElementById('state').textContent=paused?'PAUSED':'LIVE'};document.getElementById('fit').onclick=()=>{zoom=.82;panX=0;panY=0;layout()};document.getElementById('scan').onclick=()=>loadData();document.getElementById('search').oninput=e=>{const q=e.target.value.toLowerCase().trim();if(!q){selected=null;return}const n=N.find(x=>x.path.toLowerCase().includes(q));if(n){selected=n;panX=W/2-n.x*zoom;panY=H/2-n.y*zoom;document.getElementById('side').classList.add('on');document.getElementById('name').textContent=n.name;document.getElementById('path').textContent=n.path}};
async function loadData(){const l=document.getElementById('loading'),m=document.getElementById('msg');l.style.display='grid';m.textContent='Reading live server filesystem…';m.classList.remove('err');try{const ac=new AbortController;const timer=setTimeout(()=>ac.abort(),18000);const r=await fetch(location.pathname+'?scan=1&_='+Date.now(),{cache:'no-store',signal:ac.signal});clearTimeout(timer);if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();if(!Array.isArray(d.files)||!Array.isArray(d.refs))throw Error('Invalid scan data');build(d)}catch(e){m.textContent='Could not scan this server. '+(e.name==='AbortError'?'Scan timed out.':'Please check PHP filesystem permissions.');m.classList.add('err');document.getElementById('state').textContent='ERROR'}}
async function beat(){try{const r=await fetch(location.pathname+'?pulse=1&_='+Date.now(),{cache:'no-store'});const d=await r.json();if(d.ok)document.getElementById('heartbeat').textContent=d.time}catch(e){document.getElementById('heartbeat').textContent='OFFLINE'}}
requestAnimationFrame(draw);loadData();beat();setInterval(beat,3000);
</script></body></html>